import{_ as e,o,c as n,a2 as t}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"Cómo funciona","description":"","frontmatter":{},"headers":[],"relativePath":"guia/como-funciona.md","filePath":"guia/como-funciona.md","lastUpdated":1791064393000}'),s={name:"guia/como-funciona.md"};function r(l,a,i,d,u,c){return o(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h1><h2 id="cuando-entra-una-llamada" tabindex="-1">Cuando entra una llamada <a class="header-anchor" href="#cuando-entra-una-llamada" aria-label="Permalink to &quot;Cuando entra una llamada&quot;">​</a></h2><p>Antes de que suene el teléfono, Tranqui revisa el número y muestra un aviso encima de la pantalla de llamada:</p><div class="states"><div class="state-contact"><strong>✓ Verde</strong>El número está en tus contactos. Esto se decide en tu teléfono, sin consultar a nadie.</div><div class="state-identified"><strong>ⓘ Azul</strong>La comunidad identifica el número, por ejemplo &quot;Pizzería Juan&quot;.</div><div class="state-spam"><strong>⚠ Rojo</strong>La comunidad lo reportó como spam, con su etiqueta, por ejemplo &quot;Spam Claro&quot;.</div><div class="state-unknown"><strong>? Naranja</strong>No hay datos del número, es un número privado o no hubo conexión.</div></div><p>Si un número tiene varios nombres, el aviso muestra el más usado y puedes ver los demás con <strong>Otro nombre</strong>.</p><p>Si nada responde a tiempo, la llamada <strong>siempre suena</strong>: Tranqui nunca te hace perder una llamada por un error.</p><h2 id="bloquear" tabindex="-1">Bloquear <a class="header-anchor" href="#bloquear" aria-label="Permalink to &quot;Bloquear&quot;">​</a></h2><ul><li><strong>Desde el aviso</strong>, con el botón <strong>Bloquear</strong>. Las próximas llamadas de ese número no sonarán.</li><li><strong>Automáticamente</strong>, si lo activas en Ajustes: <ul><li>el spam reportado por la comunidad,</li><li>los números privados,</li><li>las llamadas internacionales.</li></ul></li></ul><p>Cada vez que bloqueamos una llamada te llega una notificación con el motivo y la hora. Tu lista de bloqueados se guarda <strong>solo en tu teléfono</strong>.</p><h2 id="despues-de-la-llamada" tabindex="-1">Después de la llamada <a class="header-anchor" href="#despues-de-la-llamada" aria-label="Permalink to &quot;Después de la llamada&quot;">​</a></h2><p>Tranqui te pregunta <strong>&quot;¿Cómo fue esta llamada?&quot;</strong> con dos opciones: <strong>Es spam</strong> o <strong>No es spam</strong>. En el <strong>Historial</strong> puedes reportar spam con una etiqueta, por ejemplo &quot;Spam Claro&quot; o &quot;Cobranzas&quot;.</p><p>Cada persona tiene un solo voto por número; si cambias de opinión, tu voto se actualiza.</p><h2 id="como-decide-la-comunidad" tabindex="-1">Cómo decide la comunidad <a class="header-anchor" href="#como-decide-la-comunidad" aria-label="Permalink to &quot;Cómo decide la comunidad&quot;">​</a></h2><ul><li>Un número se marca como spam cuando suficientes personas lo reportan y esos reportes pesan claramente más que los votos de &quot;no es spam&quot;.</li><li>Un número guardado en la agenda de muchas personas es más difícil de marcar como spam, porque eso indica que es alguien conocido.</li><li>Los votos pierden peso con el tiempo, porque los números se reasignan.</li><li>Las cuentas creadas hace menos de 7 días votan con la mitad del peso, para frenar campañas con cuentas falsas.</li><li>Un nombre solo se muestra si <strong>al menos 3 personas distintas</strong> lo usaron.</li></ul><h2 id="lo-que-necesita-en-tu-telefono" tabindex="-1">Lo que necesita en tu teléfono <a class="header-anchor" href="#lo-que-necesita-en-tu-telefono" aria-label="Permalink to &quot;Lo que necesita en tu teléfono&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permiso</th><th>Para qué</th></tr></thead><tbody><tr><td>Identificar y filtrar llamadas</td><td>Revisar quién llama antes de que suene</td></tr><tr><td>Mostrar sobre otras apps</td><td>El aviso de color encima de la llamada</td></tr><tr><td>Contactos</td><td>Mostrar en verde a quien ya conoces. Se lee solo en tu teléfono</td></tr><tr><td>Notificaciones</td><td>Avisarte de llamadas bloqueadas y preguntarte si fue spam</td></tr></tbody></table><p>La app te explica cada permiso antes de pedirlo.</p>',17)])])}const q=e(s,[["render",r]]);export{p as __pageData,q as default};
